export const TRICK_KEY = "sand_dollar";
export const TRICKS = ["lunulesift", "dollarright", "sandfilmburrow", "spinefurcreep", "petaloid", "ambulacra", "mellitahush"] as const;
export const HAPPY = ["denssand", "inksand", "densmellita"] as const;
export type SandDollarTrickKind = (typeof TRICKS)[number];
export type SandDollarHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type SandDollarTrick = {
  kind: SandDollarTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type SandDollarHappy = {
  kind: SandDollarHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { denssand: 1.70, inksand: 1.84, densmellita: 1.76 } as const;
export const MELLITAHUSH_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  mellitahush: MELLITAHUSH_HOLD + RELEASE_S,
  lunulesift: 2.48,
  dollarright: 2.42,
  sandfilmburrow: 2.40,
  spinefurcreep: 2.44,
  petaloid: 2.38,
  ambulacra: 2.56,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: SandDollarTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "mellitahush") return 40 + roll * 26;
  if (kind === "petaloid" || kind === "lunulesift" || kind === "spinefurcreep") return 12.8 + roll * 9.4;
  if (kind === "sandfilmburrow" || kind === "dollarright" || kind === "ambulacra") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

